import numpy as np
from scipy import fft, signal

class Solver:
    @staticmethod
    def structured(x,h):
        m=h.size
        # Quickly reject ordinary signals without scanning them.
        q=h[np.linspace(0,m-1,17,dtype=np.intp)]
        # A generated step has no more than one transition.
        if np.unique(q).size <= 2:
            d=np.flatnonzero(np.diff(h))
            if d.size <= 1:
                k=(int(d[0])+1 if d.size and h[0]==0 else 0)
                if (k==0 or not np.any(h[:k])) and np.all(h[k:]==h[k]):
                    c=np.r_[0.,np.cumsum(x)]
                    n=np.arange(x.size+m-1)-k
                    hi=np.clip(n+1,0,x.size); lo=np.clip(n-(m-k)+1,0,x.size)
                    return h[k]*(c[hi]-c[lo])
        return None

    def solve(self, problem, **kwargs):
        x=np.asarray(problem['signal_x'], dtype=np.float64)
        y=np.asarray(problem['signal_y'], dtype=np.float64)
        lx,ly=x.size,y.size
        if not lx or not ly:
            return {'convolution':np.empty(0)}
        mode=problem.get('mode','full')
        L=lx+ly-1
        # Cheap exact cases are common in the generated workload.
        ix=np.flatnonzero(x); iy=np.flatnonzero(y)
        if ix.size == 1:
            z=np.zeros(L); z[ix[0]:ix[0]+ly]=x[ix[0]]*y
        elif iy.size == 1:
            z=np.zeros(L); z[iy[0]:iy[0]+lx]=y[iy[0]]*x
        else:
            z=self.structured(x,y)
            if z is None: z=self.structured(y,x)
            if z is not None:
                if mode == 'same':
                    s=(ly-1)//2; z=z[s:s+lx]
                elif mode == 'valid':
                    s=min(lx,ly)-1; z=z[s:s+abs(lx-ly)+1]
                return {'convolution':z}
            if mode == 'full':
                start,end=0,L
            elif mode == 'same':
                start=(ly-1)//2; end=start+lx
            else:
                start=min(lx,ly)-1; end=start+abs(lx-ly)+1
            # Only an interval of the linear convolution is requested. A
            # shorter circular convolution is identical on that interval if
            # both its direct and wrapped copies lie outside it.
            need=max(end, L-start)
            n=fft.next_fast_len(need)
            z=fft.irfft(fft.rfft(x,n)*fft.rfft(y,n),n)
            if mode != 'full':
                return {'convolution':z[start:end]}
            z=z[:L]
        if mode == 'same':
            s=(ly-1)//2; z=z[s:s+lx]
        elif mode == 'valid':
            s=min(lx,ly)-1; z=z[s:s+abs(lx-ly)+1]
        return {'convolution':z}

