from scipy import fft, signal

class Solver:
    @staticmethod
    def _sparse_filter(x, h):
        """Fast path for steps, exponentials, sinusoids, and similar sequences."""
        m = h.size
        if m < 8:
            return np.convolve(x, h)
        # Fit recurrences only on a tiny sample first.  This makes rejection of
        # random/noisy data essentially free.
        ii = np.linspace(2, m-1, min(48, m-2), dtype=np.intp)
        hs = h[ii]
        scale = max(1., float(np.max(np.abs(h[ii]))))
        candidates = [np.array([1., -1.])]
        A = np.column_stack((h[ii-1], h[ii-2]))
        try:
            c = np.linalg.lstsq(A, -hs, rcond=None)[0]
            candidates.append(np.array([1., c[0], c[1]]))
        except Exception:
            return None
        for a in candidates:
            pred = hs.copy()
            for k in range(1, a.size): pred += a[k]*h[ii-k]
            if np.max(np.abs(pred)) > 2e-11*scale:
                continue
            # Full verification and numerator of H(z).
            b = np.convolve(h, a)
            nz = np.flatnonzero(np.abs(b) > 2e-10*max(1.,np.max(np.abs(h))))
            if nz.size <= 8:
                L=x.size+m-1
                w=np.zeros(L)
                for j in nz:
                    e=min(L-j, x.size)
                    if e > 0: w[j:j+e] += b[j]*x[:e]
                return signal.lfilter([1.0], a, w)
        return None

    def solve(self, problem, **kwargs):
        x=np.asarray(problem['signal_x'], dtype=float)
        y=np.asarray(problem['signal_y'], dtype=float)
        if x.size == 0 or y.size == 0:
            return {'convolution': np.empty(0)}
        # Exact impulses deserve a particularly cheap path.
