import scipy.sparse.linalg._matfuncs as _mf


def _fast_solve(U, V, structure=None):
    Q = (V-U).tocsc()
    P = (U+V).tocsc()
    lu = splu(Q)
    # SuperLU handles a few RHSs efficiently while retaining the same sparse
    # arithmetic zero pattern as scipy's one-column-at-a-time implementation.
    parts = []
